#include <sqlite3.h>
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "../../../lib/libbonfyre/include/bf_command_lookup.h"

static const char *arg(int argc,char **argv,const char *name){for(int i=2;i+1<argc;i++)if(!strcmp(argv[i],name))return argv[i+1];return NULL;}
static char *read_all(const char *path,size_t *n){FILE *f=fopen(path,"rb");char *b=NULL;long z;if(!f)return NULL;if(fseek(f,0,SEEK_END)||((z=ftell(f))<0)||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=malloc((size_t)z+1);if(!b){fclose(f);return NULL;}if(z&&fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}b[z]=0;fclose(f);if(n)*n=(size_t)z;return b;}
static int sql(sqlite3 *db,const char *q){char *e=NULL;int rc=sqlite3_exec(db,q,NULL,NULL,&e);if(rc!=SQLITE_OK){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);return 0;}return 1;}
static void jt(const char *s){putchar('"');for(const unsigned char*p=(const unsigned char*)(s?s:"");*p;p++){if(*p=='"'||*p=='\\'){putchar('\\');putchar(*p);}else if(*p<32)printf("\\u%04x",*p);else putchar(*p);}putchar('"');}
static int normalize(const char *in,char *out,size_t cap){size_t n=0;int sep=0;if(!in||!*in||cap<2)return 0;for(const unsigned char*p=(const unsigned char*)in;*p;p++){unsigned char c=(unsigned char)tolower(*p);if(isalnum(c)||c=='_'){if(n+1>=cap)return 0;out[n++]=(char)c;sep=0;}else if(n&&!sep){if(n+1>=cap)return 0;out[n++]='-';sep=1;}}while(n&&out[n-1]=='-')n--;out[n]=0;return n>0;}
static int init(sqlite3 *db){return sql(db,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS closure_frontier(subject TEXT NOT NULL,scope TEXT NOT NULL,tracked_at INTEGER NOT NULL,PRIMARY KEY(subject,scope));CREATE TABLE IF NOT EXISTS closure_dependency(subject TEXT NOT NULL,scope TEXT NOT NULL,dependency_ref TEXT NOT NULL,basis TEXT NOT NULL,PRIMARY KEY(subject,scope,dependency_ref,basis));CREATE INDEX IF NOT EXISTS closure_dependency_lookup ON closure_dependency(dependency_ref,subject,scope);");}
static int ins(sqlite3_stmt *st,const char *subject,const char *scope,const char *ref,const char *basis){sqlite3_reset(st);sqlite3_clear_bindings(st);sqlite3_bind_text(st,1,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(st,2,scope,-1,SQLITE_TRANSIENT);sqlite3_bind_text(st,3,ref,-1,SQLITE_TRANSIENT);sqlite3_bind_text(st,4,basis,-1,SQLITE_TRANSIENT);return sqlite3_step(st)==SQLITE_DONE;}
static int copy_identity(sqlite3 *address,sqlite3_stmt *insert,const char *subject,const char *scope,const char *identity,const char *basis){sqlite3_stmt *st=NULL;char ns[256],nc[256],ref[1024];if(!identity||!*identity)return 1;if(!ins(insert,subject,scope,identity,basis))return 0;if(sqlite3_prepare_v2(address,"SELECT dependency_ref FROM candidate_advertisement_dependency WHERE identity=?1 ORDER BY dependency_ref",-1,&st,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(st,1,identity,-1,SQLITE_TRANSIENT);while(sqlite3_step(st)==SQLITE_ROW){const char*r=(const char*)sqlite3_column_text(st,0);if(r&&*r&&!ins(insert,subject,scope,r,"address_dependency")){sqlite3_finalize(st);return 0;}}sqlite3_finalize(st);st=NULL;if(sqlite3_prepare_v2(address,"SELECT term FROM candidate_advertisement_term WHERE identity=?1 AND axis='condition' ORDER BY term",-1,&st,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(st,1,identity,-1,SQLITE_TRANSIENT);if(!normalize(subject,ns,sizeof(ns))||!normalize(scope,nc,sizeof(nc))){sqlite3_finalize(st);return 0;}while(sqlite3_step(st)==SQLITE_ROW){const char*c=(const char*)sqlite3_column_text(st,0);if(c&&*c){if(snprintf(ref,sizeof(ref),"PackCondition:%s:%s:%s",c,ns,nc)>=(int)sizeof(ref)||!ins(insert,subject,scope,ref,"activation_condition")){sqlite3_finalize(st);return 0;}}}sqlite3_finalize(st);return 1;}
static int watch_activations(sqlite3*address,sqlite3_stmt*insert,const char*subject,const char*scope){sqlite3_stmt*st=NULL;char ns[256],nc[256];if(!normalize(subject,ns,sizeof(ns))||!normalize(scope,nc,sizeof(nc)))return 0;if(sqlite3_prepare_v2(address,"SELECT DISTINCT a.identity FROM candidate_advertisement a JOIN candidate_advertisement_term s ON s.identity=a.identity AND s.axis='subject' AND s.term=?1 JOIN candidate_advertisement_term c ON c.identity=a.identity AND c.axis='scope' AND c.term=?2 WHERE a.candidate_kind='pack' ORDER BY a.identity",-1,&st,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(st,1,ns,-1,SQLITE_TRANSIENT);sqlite3_bind_text(st,2,nc,-1,SQLITE_TRANSIENT);while(sqlite3_step(st)==SQLITE_ROW){const char*i=(const char*)sqlite3_column_text(st,0);if(!copy_identity(address,insert,subject,scope,i,"activation_watch")){sqlite3_finalize(st);return 0;}}sqlite3_finalize(st);return 1;}
static int track(sqlite3 *state,sqlite3 *address,const char *path){size_t n=0;char *body=read_all(path,&n),*subject=NULL,*scope=NULL;sqlite3_stmt *meta=NULL,*ids=NULL,*insert=NULL,*del=NULL,*head=NULL,*count=NULL;int dependencies=0,identities=0,ok=0;if(!body)return 0;
 if(sqlite3_prepare_v2(state,"SELECT json_extract(?1,'$.schema'),json_extract(?1,'$.truth'),json_extract(?1,'$.subject'),json_extract(?1,'$.scope')",-1,&meta,NULL)!=SQLITE_OK)goto out;sqlite3_bind_text(meta,1,body,(int)n,SQLITE_TRANSIENT);if(sqlite3_step(meta)!=SQLITE_ROW)goto out;{const char*schema=(const char*)sqlite3_column_text(meta,0),*truth=(const char*)sqlite3_column_text(meta,1),*s=(const char*)sqlite3_column_text(meta,2),*p=(const char*)sqlite3_column_text(meta,3);if(!schema||strncmp(schema,"bonfyre-scoped-demand-closure.v",30)||!truth||strcmp(truth,"scoped_candidate_cut_exact_owner_recheck_required")||!s||!*s||!p||!*p)goto out;subject=strdup(s);scope=strdup(p);}sqlite3_finalize(meta);meta=NULL;if(!subject||!scope||!sql(state,"BEGIN IMMEDIATE;"))goto out;
 if(sqlite3_prepare_v2(state,"DELETE FROM closure_dependency WHERE subject=?1 AND scope=?2",-1,&del,NULL)!=SQLITE_OK)goto rollback;sqlite3_bind_text(del,1,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(del,2,scope,-1,SQLITE_TRANSIENT);if(sqlite3_step(del)!=SQLITE_DONE)goto rollback;sqlite3_finalize(del);del=NULL;
 if(sqlite3_prepare_v2(state,"INSERT INTO closure_frontier(subject,scope,tracked_at) VALUES(?1,?2,?3) ON CONFLICT(subject,scope) DO UPDATE SET tracked_at=excluded.tracked_at",-1,&head,NULL)!=SQLITE_OK)goto rollback;sqlite3_bind_text(head,1,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(head,2,scope,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(head,3,(sqlite3_int64)time(NULL));if(sqlite3_step(head)!=SQLITE_DONE)goto rollback;sqlite3_finalize(head);head=NULL;
 if(sqlite3_prepare_v2(state,"INSERT OR IGNORE INTO closure_dependency(subject,scope,dependency_ref,basis) VALUES(?1,?2,?3,?4)",-1,&insert,NULL)!=SQLITE_OK)goto rollback;
 if(sqlite3_prepare_v2(state,"SELECT identity,basis FROM (SELECT json_extract(value,'$.activation') identity,'pack_activation' basis FROM json_each(?1,'$.active_packs') UNION ALL SELECT json_extract(value,'$.identity'),'pack_demand' FROM json_each(?1,'$.pack_demands') UNION ALL SELECT json_extract(value,'$.identity'),'world_publication' FROM json_each(?1,'$.world_demands') UNION ALL SELECT json_extract(c.value,'$.identity'),'external_candidate' FROM json_each(?1,'$.pack_demands') d,json_each(d.value,'$.candidate_groups') g,json_each(g.value,'$.candidates') c UNION ALL SELECT json_extract(c.value,'$.identity'),'external_candidate' FROM json_each(?1,'$.world_demands') w,json_each(w.value,'$.dependencies') d,json_each(d.value,'$.candidates') c) WHERE identity IS NOT NULL AND identity<>'' ORDER BY identity,basis",-1,&ids,NULL)!=SQLITE_OK)goto rollback;sqlite3_bind_text(ids,1,body,(int)n,SQLITE_TRANSIENT);while(sqlite3_step(ids)==SQLITE_ROW){const char*i=(const char*)sqlite3_column_text(ids,0),*b=(const char*)sqlite3_column_text(ids,1);if(!copy_identity(address,insert,subject,scope,i,b))goto rollback;identities++;}sqlite3_finalize(ids);ids=NULL;if(!watch_activations(address,insert,subject,scope))goto rollback;sqlite3_finalize(insert);insert=NULL;
 if(sqlite3_prepare_v2(state,"SELECT count(DISTINCT dependency_ref) FROM closure_dependency WHERE subject=?1 AND scope=?2",-1,&count,NULL)!=SQLITE_OK)goto rollback;sqlite3_bind_text(count,1,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(count,2,scope,-1,SQLITE_TRANSIENT);if(sqlite3_step(count)==SQLITE_ROW)dependencies=sqlite3_column_int(count,0);sqlite3_finalize(count);count=NULL;if(!sql(state,"COMMIT;"))goto out;printf("{\"subject\":");jt(subject);printf(",\"scope\":");jt(scope);printf(",\"identities_recorded\":%d,\"dependency_frontier\":%d,\"truth\":\"reverse_dependency_frontier_only\"}\n",identities,dependencies);ok=1;goto out;
rollback: sql(state,"ROLLBACK;");
out: sqlite3_finalize(meta);sqlite3_finalize(ids);sqlite3_finalize(insert);sqlite3_finalize(del);sqlite3_finalize(head);sqlite3_finalize(count);free(subject);free(scope);free(body);return ok;}
static int affected(sqlite3 *db,const char *write){sqlite3_stmt *st=NULL;int first=1,count=0;if(!write||!*write)return 0;if(sqlite3_prepare_v2(db,"SELECT DISTINCT subject,scope FROM closure_dependency WHERE dependency_ref=?1 ORDER BY subject,scope",-1,&st,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(st,1,write,-1,SQLITE_TRANSIENT);fputs("{\"write\":",stdout);jt(write);fputs(",\"affected_closures\":[",stdout);while(sqlite3_step(st)==SQLITE_ROW){if(!first)putchar(',');first=0;count++;fputs("{\"subject\":",stdout);jt((const char*)sqlite3_column_text(st,0));fputs(",\"scope\":",stdout);jt((const char*)sqlite3_column_text(st,1));putchar('}');}printf("],\"affected_count\":%d,\"truth\":\"recompute_relevant_only\"}\n",count);sqlite3_finalize(st);return 1;}
static int delta(sqlite3 *db,const char *path){size_t n=0;char *body=read_all(path,&n);sqlite3_stmt *meta=NULL,*st=NULL;char *id=NULL;int first=1,count=0;if(!body)return 0;if(sqlite3_prepare_v2(db,"SELECT json_extract(?1,'$.delta_id')",-1,&meta,NULL)!=SQLITE_OK)goto fail;sqlite3_bind_text(meta,1,body,(int)n,SQLITE_TRANSIENT);if(sqlite3_step(meta)==SQLITE_ROW&&sqlite3_column_text(meta,0))id=strdup((const char*)sqlite3_column_text(meta,0));sqlite3_finalize(meta);meta=NULL;if(!id||!*id)goto fail;if(sqlite3_prepare_v2(db,"WITH writes(ref) AS (SELECT value FROM json_each(?1,'$.writes')) SELECT DISTINCT d.subject,d.scope FROM closure_dependency d JOIN writes w ON w.ref=d.dependency_ref ORDER BY d.subject,d.scope",-1,&st,NULL)!=SQLITE_OK)goto fail;sqlite3_bind_text(st,1,body,(int)n,SQLITE_TRANSIENT);fputs("{\"delta_id\":",stdout);jt(id);fputs(",\"affected_closures\":[",stdout);while(sqlite3_step(st)==SQLITE_ROW){if(!first)putchar(',');first=0;count++;fputs("{\"subject\":",stdout);jt((const char*)sqlite3_column_text(st,0));fputs(",\"scope\":",stdout);jt((const char*)sqlite3_column_text(st,1));putchar('}');}printf("],\"affected_count\":%d,\"truth\":\"recompute_relevant_only\"}\n",count);sqlite3_finalize(st);free(id);free(body);return 1;fail:sqlite3_finalize(meta);sqlite3_finalize(st);free(id);free(body);return 0;}
static void usage(void){fputs("usage: bonfyre-scoped-frontier track --db STATE --address-db ADDRESS --closure JSON\n       bonfyre-scoped-frontier affected --db STATE --write ADDRESS\n       bonfyre-scoped-frontier delta --db STATE --delta JSON\n",stderr);}
int main(int argc,char **argv){const char*dbp=arg(argc,argv,"--db");sqlite3 *db=NULL,*address=NULL;int ok=0;if(argc<2||!dbp){usage();return 2;}if(sqlite3_open(dbp,&db)!=SQLITE_OK||!init(db)){if(db)sqlite3_close(db);return 1;}enum{SF_AFFECTED,SF_DELTA,SF_TRACK};static const BfCommandEntry frontier_commands[]={{"affected",SF_AFFECTED,0,NULL},{"delta",SF_DELTA,0,NULL},{"track",SF_TRACK,0,NULL},};const BfCommandEntry*command=bf_command_lookup(frontier_commands,sizeof(frontier_commands)/sizeof(frontier_commands[0]),argv[1]);if(command&&command->id==SF_TRACK){const char*a=arg(argc,argv,"--address-db"),*c=arg(argc,argv,"--closure");if(!a||!c||sqlite3_open_v2(a,&address,SQLITE_OPEN_READONLY,NULL)!=SQLITE_OK)goto out;ok=track(db,address,c);}else if(command&&command->id==SF_AFFECTED)ok=affected(db,arg(argc,argv,"--write"));else if(command&&command->id==SF_DELTA)ok=delta(db,arg(argc,argv,"--delta"));else usage();out:if(address)sqlite3_close(address);sqlite3_close(db);return ok?0:1;}
